CREATE TABLE deployments(id BINARY(16) PRIMARY KEY,release_id BINARY(16) NOT NULL,environment_id BINARY(16) NOT NULL,status VARCHAR(30) NOT NULL,requested_by BINARY(16) NOT NULL,created_at TIMESTAMP(6) NOT NULL,started_at TIMESTAMP(6),finished_at TIMESTAMP(6),revision BIGINT NOT NULL,INDEX idx_deployment_release(release_id));
CREATE TABLE deployment_events(id BINARY(16) PRIMARY KEY,deployment_id BINARY(16) NOT NULL,from_status VARCHAR(30) NOT NULL,to_status VARCHAR(30) NOT NULL,actor_id BINARY(16) NOT NULL,message VARCHAR(1000),created_at TIMESTAMP(6) NOT NULL,INDEX idx_deployment_event(deployment_id,created_at),FOREIGN KEY(deployment_id) REFERENCES deployments(id) ON DELETE CASCADE);